export const script = "\n  (function() {\n    const btn = document.getElementById('categoryDropdownBtn');\n    const menu = document.getElementById('categoryMenu');\n    const label = document.getElementById('selectedCategoryText');\n\n    if (btn && menu && label) {\n      btn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        menu.classList.toggle('hidden');\n        menu.classList.toggle('flex');\n      });\n\n      document.querySelectorAll('.cat-item').forEach(item => {\n        item.addEventListener('click', (e) => {\n          label.textContent = item.getAttribute('data-val');\n          menu.classList.add('hidden');\n          menu.classList.remove('flex');\n        });\n      });\n\n      document.addEventListener('click', () => {\n        menu.classList.add('hidden');\n        menu.classList.remove('flex');\n      });\n    }\n  })();\n";
export const bodyClass = "bg-surface font-body-md text-on-surface antialiased";
export const scope = "mk-darkHome dark";
